<template><section class="page"><p class="eyebrow">Caisse sociale</p><h1>Demander une aide sociale</h1><form class="form" @submit.prevent="submit"><label>VOAMAMI<select v-model="form.voamami_id" required @change="loadMembers"><option value="">Sélectionner</option><option v-for="v in voamamis" :key="v.id" :value="v.id">{{v.code}} — {{v.nom}}</option></select></label><label>Membre<select v-model="form.membre_id" required><option value="">Sélectionner</option><option v-for="m in members" :key="m.id" :value="m.id">N°{{m.numero_membre}} — {{m.nom}} {{m.prenom||''}}</option></select></label><label>Type d’aide<select v-model="form.type_aide" required><option value="ACCIDENT">Accident</option><option value="MALADIE_GRAVE">Maladie grave</option><option value="DECES">Décès</option><option value="NAISSANCE">Naissance</option><option value="AUTRE">Autre</option></select></label><label>Montant demandé (Ar)<input v-model.number="form.montant_demande" type="number" min="1" required></label><label>Motif<textarea v-model="form.motif" rows="4" required></textarea></label><label>Séance (facultatif)<input v-model="form.seance_id" type="number" min="1"></label><p v-if="error" class="error">{{error}}</p><div class="actions"><button type="button" @click="$router.back()">Annuler</button><button class="primary" :disabled="saving">{{saving?'Envoi…':'Envoyer la demande'}}</button></div></form></section></template>
<script setup>import{onMounted,reactive,ref}from'vue';import{useRouter}from'vue-router';import caisseSocialeService from'../../service/caisse-sociale.service.js';import voamamiService from'../../service/voamami.service.js';import membreService from'../../service/membre.service.js';const router=useRouter(),voamamis=ref([]),members=ref([]),saving=ref(false),error=ref(''),form=reactive({voamami_id:'',membre_id:'',type_aide:'ACCIDENT',montant_demande:0,motif:'',seance_id:''});onMounted(async()=>{try{const{data}=await voamamiService.getAll();voamamis.value=data.data??[]}catch(e){error.value='Chargement impossible'}});async function loadMembers(){members.value=[];form.membre_id='';if(!form.voamami_id)return;try{const{data}=await membreService.getAll({voamami_id:form.voamami_id});members.value=data.data??data.membres??[]}catch(e){error.value='Impossible de charger les membres'}}async function submit(){saving.value=true;try{await caisseSocialeService.createAide(form.voamami_id,{...form,seance_id:form.seance_id||null});router.push('/caisse-sociale/aides')}catch(e){error.value=e.response?.data?.message||'Envoi impossible'}finally{saving.value=false}}</script>
<style scoped>.page{max-width:700px;margin:auto;padding:2rem}.eyebrow{color:#2563eb;text-transform:uppercase;font-size:.75rem;font-weight:700}.form{display:grid;gap:1rem;margin-top:1.5rem;padding:1.5rem;background:#fff;border:1px solid #e2e8f0;border-radius:1rem}label{display:grid;gap:.35rem;font-weight:600}input,select,textarea{font:inherit;padding:.7rem;border:1px solid #cbd5e1;border-radius:.5rem}.actions{display:flex;justify-content:flex-end;gap:.5rem}.actions button{border:0;padding:.7rem 1rem;border-radius:.5rem}.primary{background:#2563eb;color:#fff}.error{background:#fee2e2;color:#991b1b;padding:.7rem}
</style>
